import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.entity.decoration.ArmorStand;import net.minecraft.world.entity.MoverType;import java.nio.file.*;
@net.neoforged.fml.common.EventBusSubscriber(modid="kelmagic",value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class QaRevisionR3 {
 static final boolean ON=Boolean.getBoolean("kelmagic.r3QA");static int wait,frame=Integer.getInteger("kelmagic.r3Start",0),id,stage=-1;static boolean opened,requested,configured;static volatile boolean ready;static ArmorStand camera;
 static final BlockPos AT=new BlockPos(44,-60,-8);static final Path OUT=Path.of(System.getProperty("kelmagic.qaOutput","qa-output"));
 static final String[] NAMES={"table-front","table-side","table-neighbors","table-chapter","table-night","hair-front","hair-quarter","hair-side","hair-head65","hair-walk","hair-talk","look-up","look-overhead","look-combat-scene","look-down","throne-front","throne-seat","table-support","monocle-none","monocle-main","monocle-off","monocle-helmet","monocle-away","monocle-closed","monocle-wall","monocle-recipe","hair-root-close","hair-root-yaw-minus","hair-root-yaw-plus"};
 static void server(java.util.function.BiConsumer<net.minecraft.server.level.ServerLevel,RedMage> a){var m=Minecraft.getInstance();m.getSingleplayerServer().execute(()->{var l=m.getSingleplayerServer().overworld();if(l.getEntity(id) instanceof RedMage e)a.accept(l,e);});}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post ev){
  if(!ON)return;var m=Minecraft.getInstance();if(m.level==null){if(!opened&&m.screen instanceof TitleScreen&&++wait>20){opened=true;m.createWorldOpenFlows().openWorld("KelMagicMotionQA",()->{});}return;}if(m.player==null||m.getSingleplayerServer()==null)return;
  if(!requested){requested=true;m.getSingleplayerServer().execute(()->{var l=m.getSingleplayerServer().overworld();l.setDayTime(6000);l.setWeatherParameters(0,12000,false,false);
   for(var e:l.getEntitiesOfClass(RedMage.class,new AABB(10,-64,-40,90,-30,30)))e.discard();for(var e:l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(10,-64,-40,90,-30,30)))e.discard();
   for(BlockPos b:BlockPos.betweenClosed(40,-60,-12,48,-57,-4)){if(l.getBlockEntity(b) instanceof dev.kelmagic.archive.ArchiveTableEntity t)t.unmount();l.setBlockAndUpdate(b,Blocks.AIR.defaultBlockState());}
   for(BlockPos b:BlockPos.betweenClosed(18,-61,-32,80,-61,20))l.setBlockAndUpdate(b,Blocks.STONE.defaultBlockState());
   var p=m.getSingleplayerServer().getPlayerList().getPlayers().getFirst();QaR3Checks.server(p);p.gameMode.changeGameModeForPlayer(net.minecraft.world.level.GameType.SPECTATOR);p.connection.teleport(44.5,-59.5,-5,180,15);
   for(float yaw:new float[]{0,90,180,270}){p.setYRot(yaw);var ctx=new net.minecraft.world.item.context.BlockPlaceContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(MagicStudy.TABLE.get()),new net.minecraft.world.phys.BlockHitResult(AT.getCenter(),Direction.UP,AT.below(),false));var placed=MagicStudy.TABLE.get().getStateForPlacement(ctx);var facing=placed.getValue(dev.kelmagic.archive.ArchiveTableBlock.FACING);var front=dev.kelmagic.archive.TableOrientation.rotate(facing,new Vec3(0,0,1));double dot=front.dot(Vec3.atLowerCornerOf(p.getDirection().getNormal()));if(dot!= -1)throw new AssertionError("placement front "+yaw+" "+dot);System.out.println("PLACEMENT_PASS yaw="+yaw+" facing="+facing+" frontDotView="+dot);}
   var e=MagicCreatures.RED_MAGE.get().create(l);e.setUUID(new java.util.UUID(100,100));e.awaken();e.setNoAi(true);e.setPos(74.5,-60,8);e.setYRot(180);e.yBodyRot=e.yBodyRotO=e.yHeadRot=e.yHeadRotO=180;l.addFreshEntity(e);id=e.getId();ready=true;});return;}
  if(!ready||!(m.level.getEntity(id) instanceof RedMage e))return;
  if(!configured){configured=true;try{Files.createDirectories(OUT);}catch(Exception ex){throw new RuntimeException(ex);}m.options.enableVsync().set(false);m.options.framerateLimit().set(90);m.options.renderDistance().set(3);m.options.simulationDistance().set(5);m.options.guiScale().set(2);m.options.tutorialStep=net.minecraft.client.tutorial.TutorialSteps.NONE;m.options.hideGui=true;m.getToasts().clear();m.setScreen(null);m.resizeDisplay();camera=new ArmorStand(m.level,0,0,0);}
  int s=frame/100,t=frame%100;if(s>=NAMES.length||frame>=Integer.getInteger("kelmagic.r3End",NAMES.length*100)){System.out.println("LECTERN_HAIR_QA_COMPLETE stageIndex="+s+" startFrame="+Integer.getInteger("kelmagic.r3Start",0)+" endFrame="+frame+" IN_WORLD softwareGL");m.stop();return;}
  if(s>=15){QaR3Extras.run(m,e,s-15,t,OUT);frame++;return;}
  if(s!=stage){stage=s;System.out.println("QA_STAGE "+NAMES[s]);server((l,a)->{a.setTarget(null);a.scene(0);a.stopCharacterSpeech();a.setDeltaMovement(Vec3.ZERO);a.setPos(s<5?74.5:44.5,-60,s<5?8:-8);a.setYRot(180);a.yBodyRot=a.yBodyRotO=a.yHeadRot=a.yHeadRotO=180;
    l.setDayTime(s==4?18000:6000);for(int n=0;n<2;n++){var pos=AT.east(n);if(l.getBlockEntity(pos) instanceof dev.kelmagic.archive.ArchiveTableEntity tab)tab.unmount();l.setBlockAndUpdate(pos,s<5?MagicStudy.TABLE.get().defaultBlockState():Blocks.AIR.defaultBlockState());if(l.getBlockEntity(pos) instanceof dev.kelmagic.archive.ArchiveTableEntity tab)tab.mount(new net.minecraft.world.item.ItemStack(MagicArchive.CREATIVE_CODEX.get()));}
    var p=m.getSingleplayerServer().getPlayerList().getPlayers().getFirst();p.connection.teleport(44.5,s>=11?(s==14?-60.5:-55):-59.3,s==12?-8:-10,0,0);
    if(s>=11){a.setTarget(p);if(s==13)a.scene(10);}if(s==10){a.scene(9);a.beginCharacterSpeech("Мама попросила папу. Please bring my blue book.",RedMage.SpeechKind.DIALOGUE);}
   });MageGazeStates.clearSelection(e);if(s==8)MageGazeStates.selectPoint(e,e.getEyePosition().add(5,0,-2.33),"QA head65",6);MageEyeStates.sustainedSquint(e,s==10?.25f:0);if(s==10)MageEyeStates.burst(e);
  }
  if(s==9||s==10)server((l,a)->{a.move(MoverType.SELF,new Vec3(0,-.08,-.035));a.setYRot(180);a.yBodyRot=a.yHeadRot=180;});
  if(s<5){m.setCameraEntity(m.player);Vec3 target=dev.kelmagic.archive.TableOrientation.bookCenter(AT,MagicStudy.TABLE.get().defaultBlockState());double angle=Math.toRadians(s==1?55:0),range=s==2?2.4:1.6;double x=target.x+Math.sin(angle)*range+(s==2?.5:0),z=target.z+Math.cos(angle)*range,y=target.y-.35;aim(m.player,x,y,z,target);
   if(s==3&&t==30){var tab=(dev.kelmagic.archive.ArchiveTableEntity)m.level.getBlockEntity(AT);var view=TableBookClient.view(tab);try{var screen=view.active() instanceof CodexScreen c?c:null;if(screen!=null){var method=CodexScreen.class.getDeclaredMethod("selectSection",int.class);method.setAccessible(true);method.invoke(screen,4);}}catch(Exception ex){System.out.println("SECTION_QA "+ex);}}
   if(t==80){var hit=TableBookClient.hit();System.out.println("PAGE_HIT stage="+s+" "+hit);if(s==4)System.out.println("BLOCK_LIGHT="+m.level.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,AT.above(2)));}
  }else{m.setCameraEntity(camera);double angle=Math.toRadians(s==5?180:s==6?225:s==7?270:240),range=s==7?2.5:2.7;Vec3 target=e.position().add(0,1.35,0);aim(camera,e.getX()-Math.sin(angle)*range,e.getY()+.3,e.getZ()+Math.cos(angle)*range,target);}
  if(t==90){if(s>=11&&m.getEntityRenderDispatcher().getRenderer(e) instanceof RedMageRenderer r)r.getGeoModel().getBone("head").ifPresent(b->System.out.println("LOOK_BONE stage="+s+" pitch="+b.getRotX()+" authoritative="+(e.visualCombatTarget()!=null)+" scene="+e.scene()));Screenshot.grab(OUT.toFile(),NAMES[s]+".png",m.getMainRenderTarget(),c->{});}
  frame++;
 }
 static void aim(net.minecraft.world.entity.LivingEntity c,double x,double y,double z,Vec3 target){c.setPos(x,y,z);c.xo=x;c.yo=y;c.zo=z;double dx=target.x-x,dz=target.z-z,dy=target.y-c.getEyeY();float yaw=(float)Math.toDegrees(Math.atan2(-dx,dz)),pitch=(float)-Math.toDegrees(Math.atan2(dy,Math.hypot(dx,dz)));c.setYRot(yaw);c.yRotO=yaw;c.yHeadRot=c.yHeadRotO=c.yBodyRot=c.yBodyRotO=yaw;c.setXRot(pitch);c.xRotO=pitch;}
}
